using UnityEngine;

namespace TheLastBeat.Characters
{
    /// <summary>
    /// Trayectorias del laúd y de las muñecas durante las acciones de la bardo (tarea 28). Archivo generado desde
    /// Blender junto con los clips Bard@Note, Bard@BassDrop y Bard@DanceFloor: no lo edites a mano, porque los números
    /// tienen que coincidir con esas animaciones. Si un clip se vuelve a exportar, este archivo se regenera con él.
    ///
    /// Cada trayectoria tiene un fotograma por cada fotograma del clip (30 por segundo), repartidos de forma uniforme
    /// entre el inicio y el final del estado del Animator. Cada fotograma son 13 números (Stride):
    ///   0-2   posición del laúd respecto a donde lo cuelga LuteSocket, en los ejes locales de LuteSocket (metros)
    ///   3-6   rotación del laúd respecto a esa misma pose (cuaternión x, y, z, w)
    ///   7-9   muñeca izquierda, en los ejes locales del laúd ya movido
    ///   10-12 muñeca derecha, en los ejes locales del laúd ya movido
    /// LuteHandIK las reproduce: mueve LuteSocket y lleva las dos manos a esos puntos.
    /// </summary>
    public static class BardLuteTracks
    {
        public const int Stride = 13;

        private static readonly int NoteHash = Animator.StringToHash("Note");
        private static readonly int BassDropHash = Animator.StringToHash("BassDrop");
        private static readonly int DanceFloorHash = Animator.StringToHash("DanceFloor");

        /// <summary>Trayectoria del estado del Animator con ese nombre (shortNameHash), o null si el estado no mueve el laúd.</summary>
        public static float[] Find(int stateHash)
        {
            if (stateHash == NoteHash) return Note;
            if (stateHash == BassDropHash) return BassDrop;
            if (stateHash == DanceFloorHash) return DanceFloor;
            return null;
        }

